package net.civeira.phylax.feature.observe.observedissue.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueCursor;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueFilter;

class ObservedIssueSlider extends Slider<ObservedIssue> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedIssueCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedIssueFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ObservedIssueFilter, ObservedIssueCursor, Iterator<ObservedIssue>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ObservedIssueSlider(final Iterator<ObservedIssue> multi, final int limit,
      final BiFunction<ObservedIssueFilter, ObservedIssueCursor, Iterator<ObservedIssue>> gateway,
      final ObservedIssueFilter filter, final ObservedIssueCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param observedIssues
   * @param limit
   * @return
   */
  @Override
  public Iterator<ObservedIssue> next(List<ObservedIssue> observedIssues, int limit) {
    ObservedIssue last = observedIssues.get(observedIssues.size() - 1);
    ObservedIssueCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
